# Prints the text after the last dot
S = input()
for i in range(len(S)):
  if S[i] == ".":
    print(S[i+1:])
    break

# A leading dot marks a hidden-file name, so everything after it is printed
S = input()
last_dot_index = -1
for i in range(len(S)):
  if S[-i-1] == ".":
    last_dot_index = -i-1
    break
if last_dot_index != -1:
  print(S[last_dot_index+1:])
else:
  print("No dot found in the string.")

